{"sql": "WITH date_range AS (
    SELECT MIN(txn_date)::DATE as min_date, MAX(txn_date)::DATE as max_date FROM customer_transactions
),
num_series AS (
    SELECT row_number() OVER () - 1 as n FROM generate_series(0, 1000)
),
all_dates AS (
    SELECT (d.min_date + INTERVAL (n || ' days'))::DATE as txn_date
    FROM date_range d, num_series
    WHERE (d.min_date + INTERVAL (n || ' days')) <= d.max_date
)
SELECT * FROM all_dates LIMIT 10"}

